function weaponArtwork(){const colors=[['#382819','#76502c','#b58a50','#d2ad6c'],['#343735','#747c78','#b4bcb5','#e1e5db'],['#303638','#727c7d','#c1cdce','#eef5ed']][survival.weapon];const pixels=['................','............000.','...........0230.','..........02320.','.........02320..','........02320...','.......02320....','..00..02320.....','..02002320......','...022320.......','....0220........','...012220.......','..01200220......','.0120..00.......','.010............','..0.............'];let rects='';for(let y=0;y<16;y++)for(let x=0;x<16;x++){const c=pixels[y][x];if(c!=='.')rects+='<rect x="'+x+'" y="'+y+'" width="1" height="1" fill="'+(c==='1'?'#785332':colors[Number(c)])+'"/>';}return '<svg viewBox="0 0 16 16" width="200" height="200" shape-rendering="crispEdges" aria-hidden="true">'+rects+'</svg>';}

function refreshSurvival(){const hearts=Math.min(50,Math.ceil(survival.hp/2)),maxHearts=Math.min(50,Math.ceil(maxHealth()/2)),hunger=Math.ceil(survival.hunger/2);$('health').textContent='♥'.repeat(hearts)+'♡'.repeat(Math.max(0,maxHearts-hearts));$('health').setAttribute('aria-label','生命值 '+survival.hp.toFixed(1)+' / '+maxHealth());$('hunger').textContent='◆'.repeat(hunger)+'◇'.repeat(10-hunger);$('hunger').setAttribute('aria-label','饱食度 '+survival.hunger.toFixed(1)+' / 20');$('airBar').classList.toggle('hidden',!headUnderwater);$('airSeconds').classList.toggle('hidden',!headUnderwater);$('airBar').textContent='○'.repeat(Math.ceil(survival.air/1.5));$('airSeconds').textContent=Math.ceil(survival.air)+' 秒氧气';$('foodAmount').textContent=foodTotal();$('combatMode').textContent=survivalMode()?(survival.difficulty==='hard'?'困难生存':'标准生存'):'创造模式';$('attackFill').style.width=(activeTool==='bow'?(bowDrawing?Math.min(1,bowCharge)*100:100):Math.min(100,attackClock/weaponCooldown()*100))+'%';$('attackName').textContent=activeTool==='bow'?(bowDrawing?'蓄力 '+Math.floor(Math.min(1,bowCharge)*100)+'%':'弓 · 箭 '+homestead.arrows):survival.eating>0?'正在进食…':blocking?'举盾格挡':activeTool==='sword'?(['木剑','石剑','铁剑'][survival.weapon]+' · 耐久 '+survival.weaponDurability):'攻击冷却';$('shieldView').classList.toggle('hidden',!blocking);$('xpFill').style.width=(survival.xp%100)/100*100+'%';const aim=aimedEnemy(14);$('enemyHud').classList.toggle('hidden',!aim);if(aim){$('enemyName').textContent=(aim.name||enemyTypes[aim.type].name)+(aim.slam&&aim.windup>0?' · ⚠ 跳跃躲重击':'');$('enemyLife').style.width=Math.max(0,aim.hp/aim.maxHp*100)+'%';$('enemyHP').textContent=Math.ceil(aim.hp)+' / '+Math.ceil(aim.maxHp)}$('shieldState').textContent=survival.shield?'盾牌耐久 '+survival.shieldDurability+'/80':'未制作盾牌';$('armorState').textContent=survival.armor?'护甲：伤害降低 35%':'未装备护甲';$('weaponState').textContent=['木剑','石剑','铁剑'][survival.weapon]+' · 耐久 '+survival.weaponDurability;$('survivalStats').textContent='击败 '+survival.kills+' · 死亡 '+survival.deaths+' · 经验 '+survival.xp;$('difficulty').value=survival.difficulty;$('modeExplain').textContent=survivalMode()?'生存模式：不能飞行，会受伤、饥饿、溺水；死亡掉落背包。':'创造模式：可以飞行、无限建造、免受伤害。';document.body.classList.toggle('creative',!survivalMode());if(survival.grave)$('graveHint').textContent='掉落背包还剩 '+Math.ceil(survival.grave.ttl)+' 秒';else $('graveHint').textContent='T 腐肉回血 · G 吃食物 · R 切剑';refreshWaveHUD()}
function initializeCombat(){initializeCombatJuice();tools.sword={name:['木剑','石剑','铁剑'][survival.weapon],icon:'⚔'};initializeEnemies();$('equipSword').onclick=()=>chooseTool('sword');$('eatBtn').onclick=eatFood;$('mobileAttack').onpointerdown=e=>{e.preventDefault();$('mobileAttack').setPointerCapture(e.pointerId);if(activeTool==='bow')startBow();else{swingAttack();combatHeld=true}};$('mobileAttack').onpointerup=$('mobileAttack').onpointercancel=()=>{releaseBow();combatHeld=false};$('blockBtn').onpointerdown=e=>{e.preventDefault();$('blockBtn').setPointerCapture(e.pointerId);blocking=survival.shield&&survival.shieldDurability>0};$('blockBtn').onpointerup=$('blockBtn').onpointercancel=()=>blocking=false;$('respawnBtn').onclick=respawnPlayer;for(const kind of ['sword','sword2','shield','armor','repair'])$('craft-'+kind).onclick=()=>craftCombat(kind);$('difficulty').onchange=e=>{if(run.phase!=='prep')return;survival.difficulty=e.target.value==='hard'?'hard':'normal';save();refreshSurvival();toast('已切换为'+(survival.difficulty==='hard'?'困难':'标准')+'生存难度')};refreshSurvival();if(survival.hp<=0){survival.hp=maxHealth();survival.hunger=16;spawn()}if(!adventure.freeBuild)flight=false;}
